def tri_bulles(liste):
    n = len(liste)
    for tour in range(n - 1):
        for i in range(n - 1 - tour):
            if liste[i] > liste[i + 1]:
                liste[i], liste[i + 1] = liste[i + 1], liste[i]
    return liste

def tri_insertion(liste):
    for i in range(1, len(liste)):
        valeur = liste[i]
        j = i - 1
        while j >= 0 and liste[j] > valeur:
            liste[j + 1] = liste[j]
            j = j - 1
        liste[j + 1] = valeur
    return liste

def tri_selection(liste):
    n = len(liste)
    for i in range(n - 1):
        i_min = i
        for j in range(i + 1, n):
            if liste[j] < liste[i_min]:
                i_min = j
        liste[i], liste[i_min] = liste[i_min], liste[i]
    return liste

def recherche_lineaire(liste, cible):
    for i in range(len(liste)):
        if liste[i] == cible:
            return i
    return -1

def recherche_dichotomique(liste, cible):
    gauche = 0
    droite = len(liste) - 1
    while gauche <= droite:
        milieu = (gauche + droite) // 2
        if liste[milieu] == cible:
            return milieu
        if liste[milieu] < cible:
            gauche = milieu + 1
        else:
            droite = milieu - 1
    return -1

def etapes_lineaire(liste, cible):
    etapes = 0
    for element in liste:
        etapes = etapes + 1
        if element == cible:
            return etapes
    return etapes

def etapes_dicho(liste, cible):
    etapes = 0
    gauche = 0
    droite = len(liste) - 1
    while gauche <= droite:
        etapes = etapes + 1
        milieu = (gauche + droite) // 2
        if liste[milieu] == cible:
            return etapes
        if liste[milieu] < cible:
            gauche = milieu + 1
