def chercher_joueur(classement, pseudo):
    gauche = 0
    droite = len(classement) - 1
    while gauche <= droite:
        milieu = (gauche + droite) // 2
        if classement[milieu] == pseudo:
            return True
        if classement[milieu] < pseudo:
            gauche = milieu + 1
        else:
            droite = milieu - 1
    return False

def meilleur_score(scores):
    meilleur = scores[0]
    for s in scores:
        if s > meilleur:
            meilleur = s
    return meilleur
